class Solution {
public:
    int maxValueOfCoins(vector<vector<int>>& piles, int k) {
        vector<int> dp(k + 1, 0);
        vector<int> ndp(k + 1, 0);
        for (auto& pile : piles) {
            int m = (int)pile.size();
            vector<int> pre(m + 1, 0);
            for (int i = 0; i < m; i++) pre[i + 1] = pre[i] + pile[i];
            for (int j = 0; j <= k; j++) {
                ndp[j] = 0;
                int lim = min(m, j);
                for (int t = 0; t <= lim; t++) {
                    int val = dp[j - t] + pre[t];
                    if (val > ndp[j]) ndp[j] = val;
                }
            }
            dp.swap(ndp);
        }
        return dp[k];
    }
};
